      "example": "Think of an aircraft fly-by-wire flight envelope protection system. If wind shear or angle-of-attack sensors detect an aerodynamic stall condition, the computer automatically overrides pilot inputs, lowers the nose, and applies maximum thrust to prevent the aircraft from falling out of the sky.",
      "code": "#include <iostream>\n#include <vector>\n#include <cmath>\n#include <algorithm>\n#include <iomanip>\n\n#pragma pack(push, 1)\nstruct RawTradeMsg {\n    uint64_t timestampNs;\n    uint32_t priceTicks; // In cents or ticks\n    uint32_t volume;\n};\n#pragma pack(pop)\n\nclass alignas(64) ProductionFlowToxicityShield {\npublic:\n    static constexpr uint32_t BUCKET_SIZE = 20000;\n    static constexpr uint32_t WINDOW_N = 10;\n    static constexpr double TOXICITY_ALERT_THRESHOLD = 0.35;\n    static constexpr double EMERGENCY_KILL_THRESHOLD = 0.45;\n\nprivate:\n    // Volume bucket state\n    uint32_t m_accumulatedVolume;\n    uint32_t m_bucketStartPrice;\n    uint32_t m_bucketEndPrice;\n\n    // Rolling BVC volatility\n    double m_rollingPriceStdDev;\n\n    // Rolling VPIN circular buffer\n    uint32_t m_imbalanceBuffer[WINDOW_N];\n    size_t m_bufferIndex;\n    uint64_t m_imbalanceAccumulator;\n    bool m_windowFull;\n\n    // Current published metrics\n    double m_currentVpin;\n    bool m_killSwitchTriggered;\n\n    static double fastNormalCdf(double z) {\n        const double b1 =  0.319381530;\n        const double b2 = -0.356563782;\n        const double b3 =  1.781477937;\n        const double b4 = -1.821255978;\n        const double b5 =  1.330274429;\n        const double p  =  0.2316419;\n        const double c  =  0.3989422804014327;\n\n        if (z >= 6.0) return 1.0;\n        if (z <= -6.0) return 0.0;\n\n        double absZ = std::fabs(z);\n        double t = 1.0 / (1.0 + p * absZ);\n        double poly = ((((b5 * t + b4) * t + b3) * t + b2) * t + b1) * t;\n        double pdf = c * std::exp(-0.5 * absZ * absZ);\n        double cdf = 1.0 - pdf * poly;\n        return (z >= 0.0) ? cdf : (1.0 - cdf);\n    }\n\n    void onBucketComplete(uint32_t startPrice, uint32_t endPrice) {\n        double deltaP = static_cast<double>(static_cast<int32_t>(endPrice - startPrice)) / 100.0;\n        double z = deltaP / m_rollingPriceStdDev;\n        double buyRatio = fastNormalCdf(z);\n\n        uint32_t buyVol = static_cast<uint32_t>(std::round(BUCKET_SIZE * buyRatio));\n        uint32_t sellVol = BUCKET_SIZE - buyVol;\n        uint32_t imbalance = (buyVol >= sellVol) ? (buyVol - sellVol) : (sellVol - buyVol);\n\n        if (m_windowFull) {\n            m_imbalanceAccumulator -= m_imbalanceBuffer[m_bufferIndex];\n        }\n\n        m_imbalanceBuffer[m_bufferIndex] = imbalance;\n        m_imbalanceAccumulator += imbalance;\n        m_bufferIndex = (m_bufferIndex + 1) % WINDOW_N;\n        if (m_bufferIndex == 0) {\n            m_windowFull = true;\n        }\n\n        uint32_t activeCount = m_windowFull ? WINDOW_N : static_cast<uint32_t>(m_bufferIndex);\n        m_currentVpin = static_cast<double>(m_imbalanceAccumulator) / (static_cast<double>(activeCount) * BUCKET_SIZE);\n\n        if (m_currentVpin >= EMERGENCY_KILL_THRESHOLD) {\n            m_killSwitchTriggered = true;\n        }\n    }\n\npublic:\n    ProductionFlowToxicityShield()\n        : m_accumulatedVolume(0),\n          m_bucketStartPrice(0),\n          m_bucketEndPrice(0),\n          m_rollingPriceStdDev(0.20),\n          m_imbalanceBuffer{},\n          m_bufferIndex(0),\n          m_imbalanceAccumulator(0),\n          m_windowFull(false),\n          m_currentVpin(0.0),\n          m_killSwitchTriggered(false) {}\n\n    void onTrade(const RawTradeMsg& trade) {\n        if (m_accumulatedVolume == 0) {\n            m_bucketStartPrice = trade.priceTicks;\n        }\n        m_bucketEndPrice = trade.priceTicks;\n\n        uint32_t remaining = trade.volume;\n        while (remaining > 0) {\n            uint32_t space = BUCKET_SIZE - m_accumulatedVolume;\n            uint32_t alloc = (remaining <= space) ? remaining : space;\n            m_accumulatedVolume += alloc;\n            remaining -= alloc;\n\n            if (m_accumulatedVolume == BUCKET_SIZE) {\n                onBucketComplete(m_bucketStartPrice, m_bucketEndPrice);\n                m_accumulatedVolume = 0;\n                m_bucketStartPrice = trade.priceTicks;\n            }\n        }\n    }\n\n    double getVpin() const { return m_currentVpin; }\n    bool isKillSwitchActive() const { return m_killSwitchTriggered; }\n};\n\nint inspectProductionToxicityShield() {\n    ProductionFlowToxicityShield shield;\n\n    std::vector<RawTradeMsg> marketFeed = {\n        {1000ULL, 10000, 20000}, // Bucket 1: dP = 0\n        {2000ULL, 10000, 20000}, // Bucket 2: dP = 0\n        {3000ULL, 10000, 20000}, // Bucket 3: dP = 0\n        {4000ULL, 10000, 20000}, // Bucket 4: dP = 0\n        {5000ULL, 10000, 20000}, // Bucket 5: dP = 0\n        // Informed cascade begins\n        {6000ULL,  9960, 20000}, // Bucket 6: -$0.40 drop (z = -2.0)\n        {7000ULL,  9910, 20000}, // Bucket 7: -$0.50 drop (z = -2.5)\n        {8000ULL,  9840, 20000}, // Bucket 8: -$0.70 drop (z = -3.5)\n        {9000ULL,  9750, 20000}, // Bucket 9: -$0.90 drop (z = -4.5)\n        {10000ULL, 9600, 20000}  // Bucket 10: -$1.50 drop (z = -7.5) -> Severe toxicity!\n    };\n\n    std::cout << \"--- Production Flow Toxicity Shield Benchmark ---\\n\";\n    for (size_t i = 0; i < marketFeed.size(); ++i) {\n        shield.onTrade(marketFeed[i]);\n        std::cout << \"Trade #\" << (i + 1) \n                  << \" | Price: $\" << std::fixed << std::setprecision(2) << (marketFeed[i].priceTicks / 100.0)\n                  << \" | Current VPIN: \" << std::setprecision(4) << shield.getVpin()\n                  << \" | KillSwitch: \" << (shield.isKillSwitchActive() ? \"ACTIVATED (HALT QUOTING)\" : \"ARMED / NORMAL\") \n                  << \"\\n\";\n    }\n    return 0;\n}\n\nint main() {\n    return inspectProductionToxicityShield();\n}",
