      "code": "#include <iostream>\n#include <iomanip>\n#include <string>\n#include <vector>\n\nstruct SubsystemLatencyBudget {\n    std::string subsystem;\n    int budgeted_ns;\n    std::string hardware_layer;\n};\n\nint main() {\n    std::cout << \"=== PRINCIPAL ARCHITECT RFC-001: LATENCY BUDGET (SUB-800ns) ===\\n\";\n    std::vector<SubsystemLatencyBudget> budgets = {\n        {\"PHY & MAC Deserialization\",  75, \"Solarflare FPGA NIC\"},\n        {\"Kernel-Bypass Parsing\",    120, \"User-space DPDK / Onload\"},\n        {\"L3 Book & Micro-Price\",     150, \"Lock-free C++ Ring Buffer\"},\n        {\"Alpha & Signal Logic\",      200, \"AVX-512 Vectorized Engine\"},\n        {\"Pre-Trade Risk Gate\",       100, \"In-line FPGA Hardware Gating\"},\n        {\"OUCH Serialization & TX\",  155, \"Cut-Through MAC Egress\"}\n    };\n    \n    int total_budget_ns = 0;\n    std::cout << std::left << std::setw(28) << \"Subsystem Pipeline\"\n              << std::setw(15) << \"Budget (ns)\"\n              << \"Hardware Execution Layer\\n\";\n    std::cout << \"----------------------------------------------------------------------\\n\";\n    for (const auto& b : budgets) {\n        total_budget_ns += b.budgeted_ns;\n        std::cout << std::left << std::setw(28) << b.subsystem\n                  << std::setw(15) << b.budgeted_ns\n                  << b.hardware_layer << \"\\n\";\n    }\n    std::cout << \"----------------------------------------------------------------------\\n\";\n    std::cout << \"Total Pipeline Budget: \" << total_budget_ns << \" ns (Safety Buffer: \"\n              << (800 - total_budget_ns) << \" ns) -> [COMPLIANT]\\n\";\n    return 0;\n}",
